# Auto-generated static content bundle for serverless runtime

INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>HygieNet Cloud — IoT Sanitary Vending Machine Dashboard</title>\n  <meta name="description" content="Next-Gen Cloud IoT Sanitary Vending Machine Management System powered by Arduino UNO R4 WiFi, Vercel Serverless, and MongoDB Atlas.">\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Outfit:wght@500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">\n  <link rel="stylesheet" href="style.css">\n</head>\n<body>\n  <!-- Ambient background glow effects -->\n  <div class="ambient-glow glow-1"></div>\n  <div class="ambient-glow glow-2"></div>\n\n  <div class="app-shell">\n    <!-- Top Navigation Bar -->\n    <header class="top-nav">\n      <div class="brand-group">\n        <div class="brand-logo">\n          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">\n            <path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>\n          </svg>\n        </div>\n        <div class="brand-text">\n          <div class="brand-title">HygieNet <span>Cloud</span></div>\n          <div class="brand-subtitle">IoT Rural Women\'s Sanitary Solution • MMMUT Gorakhpur</div>\n        </div>\n      </div>\n\n      <div class="nav-status-items">\n        <div class="status-pill" id="cloud-status-pill">\n          <span class="status-indicator-dot online"></span>\n          <span id="cloud-status-text">Cloud API Live</span>\n        </div>\n        <div class="status-pill" id="device-status-pill">\n          <span class="status-indicator-dot pulse-emerald"></span>\n          <span id="device-status-text">UNO R4 WiFi: Ready</span>\n        </div>\n        <button class="btn btn-secondary btn-sm" id="btn-refresh" onclick="fetchDashboardData()">\n          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">\n            <polyline points="23 4 23 10 17 10"></polyline>\n            <polyline points="1 20 1 14 7 14"></polyline>\n            <path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"></path>\n          </svg>\n          Sync\n        </button>\n      </div>\n    </header>\n\n    <!-- Main Content Container -->\n    <main class="main-container">\n      \n      <!-- Metrics Overview Cards -->\n      <section class="metrics-grid">\n        <div class="metric-card">\n          <div class="metric-header">\n            <span class="metric-label">Total Dispensed</span>\n            <div class="metric-icon icon-emerald">\n              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"></rect><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path></svg>\n            </div>\n          </div>\n          <div class="metric-value" id="stat-total-dispensed">0</div>\n          <div class="metric-trend"><span class="trend-highlight">Pads</span> lifetime delivered</div>\n        </div>\n\n        <div class="metric-card">\n          <div class="metric-header">\n            <span class="metric-label">Today\'s Transactions</span>\n            <div class="metric-icon icon-teal">\n              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg>\n            </div>\n          </div>\n          <div class="metric-value" id="stat-today-tx">0</div>\n          <div class="metric-trend"><span class="trend-highlight">Scans</span> logged today</div>\n        </div>\n\n        <div class="metric-card">\n          <div class="metric-header">\n            <span class="metric-label">Beneficiaries</span>\n            <div class="metric-icon icon-cyan">\n              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M23 21v-2a4 4 0 0 0-3-3.87"></path><path d="M16 3.13a4 4 0 0 1 0 7.75"></path></svg>\n            </div>\n          </div>\n          <div class="metric-value" id="stat-active-users">0</div>\n          <div class="metric-trend"><span class="trend-highlight">Registered</span> RFID cards</div>\n        </div>\n\n        <div class="metric-card">\n          <div class="metric-header">\n            <span class="metric-label">Monthly Pad Limit</span>\n            <div class="metric-icon icon-indigo">\n              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg>\n            </div>\n          </div>\n          <div class="metric-value" id="stat-monthly-limit">5</div>\n          <div class="metric-trend"><span class="trend-highlight">Quota</span> per beneficiary / month</div>\n        </div>\n      </section>\n\n      <!-- Database & Architecture Banner -->\n      <section class="banner-card" id="db-status-banner">\n        <div class="banner-content">\n          <div class="banner-badge" id="db-badge">MongoDB Atlas Cloud</div>\n          <div class="banner-title" id="db-title">Cloud Storage Connected</div>\n          <div class="banner-desc" id="db-desc">Synchronized in real-time with MongoDB Atlas cluster. Vercel serverless authorization engine is active.</div>\n        </div>\n        <div class="banner-actions">\n          <button class="btn btn-primary btn-sm" id="btn-open-simulator" onclick="toggleSimulator()">\n            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>\n            Hardware & RFID Simulator\n          </button>\n        </div>\n      </section>\n\n      <!-- Interactive Hardware Simulator (Drawer/Card) -->\n      <section class="simulator-section card-glass hidden" id="simulator-container">\n        <div class="simulator-header">\n          <div class="simulator-title-group">\n            <span class="badge badge-emerald">Interactive Testbed</span>\n            <h3>Arduino UNO R4 WiFi & Dispenser Simulator</h3>\n            <p>Test RFID card authentication, quota calculation, button selection, and dual-servo dispensing live in your browser.</p>\n          </div>\n          <button class="btn-icon" onclick="toggleSimulator()" title="Close Simulator">✕</button>\n        </div>\n\n        <div class="simulator-body">\n          <!-- Left: Virtual Machine Display & Controls -->\n          <div class="virtual-device">\n            <div class="oled-frame">\n              <div class="oled-glass" id="sim-oled">\n                <div class="oled-line-1" id="sim-oled-line1">HYGIENET R4</div>\n                <div class="oled-line-2" id="sim-oled-line2">READY TO SCAN</div>\n                <div class="oled-line-3" id="sim-oled-line3">TAP RFID CARD</div>\n              </div>\n            </div>\n\n            <div class="virtual-buttons">\n              <button class="btn-hw" id="hw-btn-inc" onclick="simAdjustQty(1)" title="Increment Quantity (+)">+</button>\n              <button class="btn-hw" id="hw-btn-dec" onclick="simAdjustQty(-1)" title="Decrement Quantity (-)">−</button>\n              <button class="btn-hw btn-hw-confirm" id="hw-btn-conf" onclick="simConfirmDispense()" title="Confirm Dispense">CONFIRM</button>\n            </div>\n\n            <!-- Virtual Servos Animation -->\n            <div class="servos-visualization">\n              <div class="servo-item">\n                <div class="servo-label">ARM SERVO (Pin A3)</div>\n                <div class="servo-track"><div class="servo-indicator" id="sim-servo-arm"></div></div>\n              </div>\n              <div class="servo-item">\n                <div class="servo-label">GATE SERVO (Pin 8)</div>\n                <div class="servo-track"><div class="servo-indicator" id="sim-servo-gate"></div></div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Right: Quick Tap Presets -->\n          <div class="simulator-controls">\n            <h4 class="subheading">Quick Tap Test Cards</h4>\n            <div class="test-cards-list">\n              <button class="test-card-btn" onclick="simTapCard(\'C3:27:87:14\')">\n                <div class="test-card-name">Sunita Yadav</div>\n                <div class="test-card-uid">UID: C3:27:87:14</div>\n                <span class="badge badge-emerald">Registered (5/mo)</span>\n              </button>\n              <button class="test-card-btn" onclick="simTapCard(\'E3:A5:AE:02\')">\n                <div class="test-card-name">Anita Kumari</div>\n                <div class="test-card-uid">UID: E3:A5:AE:02</div>\n                <span class="badge badge-emerald">Registered (5/mo)</span>\n              </button>\n              <button class="test-card-btn" onclick="simTapCard(\'D7:EE:26:03\')">\n                <div class="test-card-name">Unknown Card</div>\n                <div class="test-card-uid">UID: D7:EE:26:03</div>\n                <span class="badge badge-warn">Unregistered Card</span>\n              </button>\n            </div>\n\n            <div class="custom-card-input">\n              <input type="text" id="sim-custom-uid" placeholder="Custom UID (e.g. AA:BB:CC:DD)" class="form-input">\n              <button class="btn btn-secondary btn-sm" onclick="simTapCustomCard()">Tap Custom UID</button>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- Main Two Column Grid: Users and Transactions -->\n      <div class="two-col-grid">\n        <!-- Beneficiaries Card -->\n        <section class="content-card card-glass">\n          <div class="card-toolbar">\n            <div class="card-title-group">\n              <h3>Registered Beneficiaries</h3>\n              <p>Monthly pad limits and real-time usage quotas</p>\n            </div>\n            <div class="card-actions">\n              <button class="btn btn-secondary btn-sm" onclick="openAddUserModal()">\n                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>\n                Add User\n              </button>\n              <button class="btn btn-danger-subtle btn-sm" onclick="confirmResetAll()">\n                Reset Monthly\n              </button>\n            </div>\n          </div>\n\n          <div class="table-responsive">\n            <table class="data-table" id="users-table">\n              <thead>\n                <tr>\n                  <th>Beneficiary</th>\n                  <th>RFID UID</th>\n                  <th>Quota Used</th>\n                  <th>Remaining</th>\n                  <th>Status</th>\n                  <th>Action</th>\n                </tr>\n              </thead>\n              <tbody id="users-tbody">\n                <tr><td colspan="6" class="text-center text-muted py-4">Loading registered beneficiaries...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </section>\n\n        <!-- Transactions Ledger Card -->\n        <section class="content-card card-glass">\n          <div class="card-toolbar">\n            <div class="card-title-group">\n              <h3>Live Dispense Ledger</h3>\n              <p>Cloud audit log synchronized with Uno R4 WiFi</p>\n            </div>\n            <div class="live-pulse-badge">\n              <span class="status-indicator-dot online"></span>\n              Live Sync\n            </div>\n          </div>\n\n          <div class="table-responsive">\n            <table class="data-table" id="tx-table">\n              <thead>\n                <tr>\n                  <th>Beneficiary</th>\n                  <th>UID</th>\n                  <th>Qty</th>\n                  <th>Status</th>\n                  <th>Timestamp</th>\n                </tr>\n              </thead>\n              <tbody id="tx-tbody">\n                <tr><td colspan="5" class="text-center text-muted py-4">No dispense activity yet</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </section>\n      </div>\n\n    </main>\n  </div>\n\n  <!-- Add / Edit Beneficiary Modal -->\n  <div class="modal-backdrop hidden" id="user-modal">\n    <div class="modal-box">\n      <div class="modal-header">\n        <h3 id="modal-title">Register Beneficiary Card</h3>\n        <button class="btn-icon" onclick="closeUserModal()">✕</button>\n      </div>\n      <form id="user-form" onsubmit="handleUserSubmit(event)">\n        <div class="form-group">\n          <label for="form-name">Beneficiary Name</label>\n          <input type="text" id="form-name" class="form-input" placeholder="e.g. Priya Sharma" required>\n        </div>\n        <div class="form-group">\n          <label for="form-uid">RFID Card UID</label>\n          <input type="text" id="form-uid" class="form-input font-mono" placeholder="e.g. C3:27:87:14" required>\n          <span class="field-hint">Format: 8-10 hex characters separated by colons</span>\n        </div>\n        <div class="form-group">\n          <label for="form-limit">Monthly Limit (Pads)</label>\n          <input type="number" id="form-limit" class="form-input" value="5" min="1" max="20" required>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn btn-secondary" onclick="closeUserModal()">Cancel</button>\n          <button type="submit" class="btn btn-primary">Save Beneficiary</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- Toast Notification Container -->\n  <div class="toast-container" id="toast-container"></div>\n\n  <script src="app.js"></script>\n</body>\n</html>\n'

STYLE_CSS = "/* ============================================================\n   HygieNet Cloud Edition — Modern Glassmorphic Design System\n   ============================================================ */\n\n:root {\n  --bg-main: #090e1a;\n  --bg-surface: rgba(18, 26, 44, 0.75);\n  --bg-surface-elevated: rgba(26, 38, 64, 0.85);\n  --bg-card: rgba(15, 23, 42, 0.65);\n  --border-subtle: rgba(255, 255, 255, 0.08);\n  --border-hover: rgba(16, 185, 129, 0.35);\n  \n  --primary: #10b981;\n  --primary-hover: #059669;\n  --primary-glow: rgba(16, 185, 129, 0.3);\n  --teal: #14b8a6;\n  --cyan: #06b6d4;\n  --indigo: #6366f1;\n  \n  --text-main: #f8fafc;\n  --text-muted: #94a3b8;\n  --text-dim: #64748b;\n  \n  --status-ok-bg: rgba(16, 185, 129, 0.15);\n  --status-ok-text: #34d399;\n  --status-warn-bg: rgba(245, 158, 11, 0.15);\n  --status-warn-text: #fbbf24;\n  --status-err-bg: rgba(239, 68, 68, 0.15);\n  --status-err-text: #f87171;\n  \n  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;\n  --font-display: 'Outfit', sans-serif;\n  --font-mono: 'JetBrains Mono', monospace;\n  \n  --radius-sm: 8px;\n  --radius-md: 12px;\n  --radius-lg: 18px;\n  --radius-xl: 24px;\n  \n  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: var(--font-sans);\n  background-color: var(--bg-main);\n  color: var(--text-main);\n  min-height: 100vh;\n  line-height: 1.5;\n  overflow-x: hidden;\n  position: relative;\n}\n\n/* Ambient dynamic background glow */\n.ambient-glow {\n  position: fixed;\n  border-radius: 50%;\n  filter: blur(140px);\n  pointer-events: none;\n  z-index: 0;\n}\n\n.glow-1 {\n  width: 500px;\n  height: 500px;\n  background: radial-gradient(circle, rgba(16, 185, 129, 0.12) 0%, transparent 70%);\n  top: -100px;\n  left: 10%;\n}\n\n.glow-2 {\n  width: 600px;\n  height: 600px;\n  background: radial-gradient(circle, rgba(6, 182, 212, 0.08) 0%, transparent 70%);\n  bottom: -150px;\n  right: 5%;\n}\n\n/* App Shell */\n.app-shell {\n  position: relative;\n  z-index: 1;\n  display: flex;\n  flex-direction: column;\n  min-height: 100vh;\n}\n\n/* Top Navigation */\n.top-nav {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 18px 36px;\n  background: rgba(9, 14, 26, 0.7);\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  border-bottom: 1px solid var(--border-subtle);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n}\n\n.brand-group {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.brand-logo {\n  width: 44px;\n  height: 44px;\n  background: linear-gradient(135deg, #10b981, #06b6d4);\n  border-radius: var(--radius-md);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: #fff;\n  box-shadow: 0 4px 20px var(--primary-glow);\n}\n\n.brand-title {\n  font-family: var(--font-display);\n  font-size: 20px;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  color: #fff;\n}\n\n.brand-title span {\n  color: var(--primary);\n  font-weight: 800;\n}\n\n.brand-subtitle {\n  font-size: 12px;\n  color: var(--text-dim);\n  font-weight: 400;\n}\n\n.nav-status-items {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.status-pill {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 14px;\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--text-muted);\n}\n\n.status-indicator-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n}\n\n.status-indicator-dot.online {\n  background-color: var(--primary);\n  box-shadow: 0 0 10px var(--primary);\n}\n\n.status-indicator-dot.pulse-emerald {\n  background-color: var(--primary);\n  animation: pulse-dot 2s infinite;\n}\n\n@keyframes pulse-dot {\n  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.7); }\n  70% { transform: scale(1); box-shadow: 0 0 0 8px rgba(16, 185, 129, 0); }\n  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }\n}\n\n/* Main Container */\n.main-container {\n  flex: 1;\n  max-width: 1400px;\n  width: 100%;\n  margin: 0 auto;\n  padding: 32px 36px;\n  display: flex;\n  flex-direction: column;\n  gap: 28px;\n}\n\n/* Metrics Grid */\n.metrics-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 20px;\n}\n\n.metric-card {\n  background: var(--bg-card);\n  backdrop-filter: blur(14px);\n  -webkit-backdrop-filter: blur(14px);\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-lg);\n  padding: 22px 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  transition: var(--transition);\n}\n\n.metric-card:hover {\n  transform: translateY(-3px);\n  border-color: var(--border-hover);\n  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.25);\n}\n\n.metric-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.metric-label {\n  font-size: 13px;\n  font-weight: 500;\n  color: var(--text-muted);\n  letter-spacing: 0.02em;\n}\n\n.metric-icon {\n  width: 38px;\n  height: 38px;\n  border-radius: var(--radius-sm);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.icon-emerald { background: rgba(16, 185, 129, 0.12); color: #34d399; }\n.icon-teal { background: rgba(20, 184, 166, 0.12); color: #2dd4bf; }\n.icon-cyan { background: rgba(6, 182, 212, 0.12); color: #38bdf8; }\n.icon-indigo { background: rgba(99, 102, 241, 0.12); color: #818cf8; }\n\n.metric-value {\n  font-family: var(--font-display);\n  font-size: 34px;\n  font-weight: 700;\n  color: #fff;\n  letter-spacing: -0.02em;\n}\n\n.metric-trend {\n  font-size: 12px;\n  color: var(--text-dim);\n}\n\n.trend-highlight {\n  color: var(--primary);\n  font-weight: 600;\n}\n\n/* Banner Card */\n.banner-card {\n  background: linear-gradient(135deg, rgba(16, 185, 129, 0.15) 0%, rgba(6, 182, 212, 0.08) 100%);\n  border: 1px solid rgba(16, 185, 129, 0.25);\n  border-radius: var(--radius-lg);\n  padding: 22px 28px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 16px;\n}\n\n.banner-badge {\n  display: inline-block;\n  padding: 4px 10px;\n  background: rgba(16, 185, 129, 0.2);\n  border: 1px solid rgba(16, 185, 129, 0.4);\n  border-radius: 999px;\n  font-size: 11px;\n  font-weight: 600;\n  color: #6ee7b7;\n  margin-bottom: 6px;\n}\n\n.banner-title {\n  font-family: var(--font-display);\n  font-size: 17px;\n  font-weight: 600;\n  color: #fff;\n}\n\n.banner-desc {\n  font-size: 13px;\n  color: var(--text-muted);\n  max-width: 680px;\n  margin-top: 2px;\n}\n\n/* Simulator Container */\n.simulator-section {\n  padding: 26px 30px;\n  border-radius: var(--radius-xl);\n  background: var(--bg-surface-elevated);\n  border: 1px solid rgba(16, 185, 129, 0.3);\n  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.4);\n}\n\n.simulator-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  margin-bottom: 24px;\n}\n\n.simulator-title-group h3 {\n  font-family: var(--font-display);\n  font-size: 18px;\n  font-weight: 600;\n  margin-top: 6px;\n}\n\n.simulator-title-group p {\n  font-size: 13px;\n  color: var(--text-muted);\n}\n\n.simulator-body {\n  display: grid;\n  grid-template-columns: 340px 1fr;\n  gap: 32px;\n}\n\n@media (max-width: 860px) {\n  .simulator-body { grid-template-columns: 1fr; }\n}\n\n/* Virtual Device UI */\n.virtual-device {\n  background: #020617;\n  border: 2px solid #1e293b;\n  border-radius: var(--radius-lg);\n  padding: 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  box-shadow: inset 0 2px 8px rgba(0,0,0,0.8);\n}\n\n.oled-frame {\n  background: #090e17;\n  border: 3px solid #334155;\n  border-radius: var(--radius-sm);\n  padding: 16px 12px;\n  box-shadow: inset 0 0 20px rgba(0, 255, 180, 0.08);\n}\n\n.oled-glass {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  min-height: 90px;\n  font-family: var(--font-mono);\n  color: #38bdf8;\n  text-shadow: 0 0 8px rgba(56, 189, 248, 0.6);\n  text-align: center;\n}\n\n.oled-line-1 { font-size: 14px; font-weight: 700; letter-spacing: 0.05em; margin-bottom: 4px; }\n.oled-line-2 { font-size: 18px; font-weight: 800; color: #a7f3d0; text-shadow: 0 0 10px rgba(167, 243, 208, 0.8); }\n.oled-line-3 { font-size: 12px; color: #94a3b8; margin-top: 6px; }\n\n.virtual-buttons {\n  display: flex;\n  gap: 10px;\n}\n\n.btn-hw {\n  flex: 1;\n  background: #1e293b;\n  border: 1px solid #475569;\n  color: #f1f5f9;\n  font-family: var(--font-mono);\n  font-size: 18px;\n  font-weight: 700;\n  border-radius: var(--radius-sm);\n  padding: 12px 0;\n  cursor: pointer;\n  transition: var(--transition);\n  box-shadow: 0 4px #0f172a;\n}\n\n.btn-hw:active {\n  transform: translateY(3px);\n  box-shadow: 0 1px #0f172a;\n}\n\n.btn-hw-confirm {\n  flex: 2;\n  background: #065f46;\n  border-color: #10b981;\n  color: #ecfdf5;\n  font-size: 13px;\n  letter-spacing: 0.05em;\n}\n\n.servos-visualization {\n  background: #0f172a;\n  border-radius: var(--radius-sm);\n  padding: 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  border: 1px solid #1e293b;\n}\n\n.servo-label {\n  font-size: 10px;\n  font-family: var(--font-mono);\n  color: #64748b;\n  margin-bottom: 4px;\n}\n\n.servo-track {\n  height: 8px;\n  background: #1e293b;\n  border-radius: 4px;\n  position: relative;\n  overflow: hidden;\n}\n\n.servo-indicator {\n  position: absolute;\n  top: 0;\n  left: 0;\n  height: 100%;\n  width: 25%;\n  background: var(--primary);\n  border-radius: 4px;\n  transition: all 0.4s ease;\n}\n\n.servo-indicator.actuated {\n  left: 75%;\n  background: #38bdf8;\n  box-shadow: 0 0 10px #38bdf8;\n}\n\n/* Simulator Test Card Buttons */\n.test-cards-list {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 12px;\n  margin-top: 10px;\n}\n\n.test-card-btn {\n  background: var(--bg-card);\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-md);\n  padding: 14px 16px;\n  text-align: left;\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.test-card-btn:hover {\n  border-color: var(--border-hover);\n  background: rgba(16, 185, 129, 0.08);\n  transform: translateY(-2px);\n}\n\n.test-card-name { font-weight: 600; font-size: 14px; color: #fff; }\n.test-card-uid { font-family: var(--font-mono); font-size: 11px; color: var(--text-dim); margin: 4px 0 8px; }\n\n.custom-card-input {\n  display: flex;\n  gap: 10px;\n  margin-top: 16px;\n}\n\n/* Two Column Tables Layout */\n.two-col-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 24px;\n}\n\n@media (max-width: 1080px) {\n  .two-col-grid { grid-template-columns: 1fr; }\n}\n\n.card-glass {\n  background: var(--bg-card);\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-lg);\n  padding: 24px;\n}\n\n.card-toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 20px;\n  flex-wrap: wrap;\n  gap: 12px;\n}\n\n.card-title-group h3 {\n  font-family: var(--font-display);\n  font-size: 17px;\n  font-weight: 600;\n  color: #fff;\n}\n\n.card-title-group p {\n  font-size: 12px;\n  color: var(--text-dim);\n}\n\n.live-pulse-badge {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 12px;\n  color: var(--primary);\n  font-weight: 500;\n}\n\n/* Tables */\n.table-responsive {\n  width: 100%;\n  overflow-x: auto;\n}\n\n.data-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 13px;\n  text-align: left;\n}\n\n.data-table th {\n  padding: 12px 14px;\n  background: rgba(255, 255, 255, 0.02);\n  color: var(--text-dim);\n  font-weight: 600;\n  border-bottom: 1px solid var(--border-subtle);\n  letter-spacing: 0.02em;\n}\n\n.data-table td {\n  padding: 13px 14px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.04);\n  color: var(--text-main);\n  vertical-align: middle;\n}\n\n.data-table tr:hover td {\n  background: rgba(255, 255, 255, 0.02);\n}\n\n/* Progress bar inside table */\n.progress-wrap {\n  background: rgba(255, 255, 255, 0.08);\n  border-radius: 999px;\n  height: 7px;\n  width: 90px;\n  overflow: hidden;\n  margin-top: 4px;\n}\n\n.progress-bar {\n  background: var(--primary);\n  height: 100%;\n  border-radius: 999px;\n  transition: width 0.3s ease;\n}\n\n.progress-bar.limit-reached {\n  background: #f59e0b;\n}\n\n/* Badges */\n.badge {\n  display: inline-flex;\n  align-items: center;\n  padding: 3px 9px;\n  border-radius: 999px;\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n}\n\n.badge-emerald { background: var(--status-ok-bg); color: var(--status-ok-text); }\n.badge-warn { background: var(--status-warn-bg); color: var(--status-warn-text); }\n.badge-err { background: var(--status-err-bg); color: var(--status-err-text); }\n\n/* Buttons */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 7px;\n  padding: 8px 16px;\n  border-radius: var(--radius-sm);\n  font-size: 13px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: var(--transition);\n  border: none;\n  font-family: inherit;\n}\n\n.btn-sm { padding: 6px 12px; font-size: 12px; }\n\n.btn-primary {\n  background: var(--primary);\n  color: #042f1f;\n  font-weight: 600;\n}\n\n.btn-primary:hover {\n  background: var(--primary-hover);\n  color: #fff;\n  box-shadow: 0 4px 14px var(--primary-glow);\n}\n\n.btn-secondary {\n  background: rgba(255, 255, 255, 0.06);\n  color: var(--text-main);\n  border: 1px solid var(--border-subtle);\n}\n\n.btn-secondary:hover {\n  background: rgba(255, 255, 255, 0.12);\n  border-color: rgba(255, 255, 255, 0.15);\n}\n\n.btn-danger-subtle {\n  background: rgba(239, 68, 68, 0.1);\n  color: #f87171;\n  border: 1px solid rgba(239, 68, 68, 0.2);\n}\n\n.btn-danger-subtle:hover {\n  background: rgba(239, 68, 68, 0.2);\n}\n\n.btn-icon {\n  background: transparent;\n  border: none;\n  color: var(--text-dim);\n  font-size: 16px;\n  cursor: pointer;\n  padding: 4px;\n}\n\n.btn-icon:hover { color: #fff; }\n\n/* Forms & Inputs */\n.form-group {\n  margin-bottom: 16px;\n}\n\n.form-group label {\n  display: block;\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--text-muted);\n  margin-bottom: 6px;\n}\n\n.form-input {\n  width: 100%;\n  padding: 10px 14px;\n  background: rgba(15, 23, 42, 0.8);\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-sm);\n  color: #fff;\n  font-size: 13px;\n  font-family: inherit;\n  outline: none;\n  transition: var(--transition);\n}\n\n.form-input:focus {\n  border-color: var(--primary);\n  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.15);\n}\n\n.field-hint {\n  font-size: 11px;\n  color: var(--text-dim);\n  margin-top: 4px;\n  display: block;\n}\n\n/* Modal */\n.modal-backdrop {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background: rgba(0, 0, 0, 0.7);\n  backdrop-filter: blur(8px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 1000;\n}\n\n.modal-box {\n  background: #0f172a;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-lg);\n  width: 100%;\n  max-width: 440px;\n  padding: 24px;\n  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);\n}\n\n.modal-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 20px;\n}\n\n.modal-header h3 {\n  font-family: var(--font-display);\n  font-size: 17px;\n}\n\n.modal-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 10px;\n  margin-top: 24px;\n}\n\n/* Toast Notifications */\n.toast-container {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  z-index: 2000;\n}\n\n.toast {\n  padding: 12px 18px;\n  background: #1e293b;\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-sm);\n  color: #fff;\n  font-size: 13px;\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);\n  animation: slide-in 0.3s ease;\n}\n\n.toast.toast-success { border-left: 4px solid var(--primary); }\n.toast.toast-error { border-left: 4px solid #ef4444; }\n\n@keyframes slide-in {\n  from { transform: translateX(100%); opacity: 0; }\n  to { transform: translateX(0); opacity: 1; }\n}\n\n/* Utilities */\n.hidden { display: none !important; }\n.font-mono { font-family: var(--font-mono); }\n.text-center { text-align: center; }\n.text-muted { color: var(--text-muted); }\n.py-4 { padding-top: 24px; padding-bottom: 24px; }\n.subheading { font-size: 13px; font-weight: 600; color: var(--text-muted); margin-bottom: 8px; }\n"

APP_JS = '// ============================================================\n//  HygieNet Cloud Edition — Admin Dashboard & Simulator JS\n// ============================================================\n\nlet currentSimState = {\n  activeUid: null,\n  activeName: null,\n  remaining: 0,\n  selectedQty: 1,\n  maxSelectable: 0,\n  isBusy: false\n};\n\n// Polling interval\nlet pollTimer = null;\n\ndocument.addEventListener(\'DOMContentLoaded\', () => {\n  fetchDashboardData();\n  pollTimer = setInterval(fetchDashboardData, 5000);\n});\n\n// ------------------------------------------------------------\n//  DASHBOARD DATA FETCHING & RENDERING\n// ------------------------------------------------------------\n\nasync function fetchDashboardData() {\n  try {\n    const [statsRes, usersRes, txRes] = await Promise.all([\n      fetch(\'/api/dashboard/stats\').then(r => r.json()),\n      fetch(\'/api/users\').then(r => r.json()),\n      fetch(\'/api/transactions?limit=20\').then(r => r.json())\n    ]);\n\n    renderStats(statsRes);\n    renderUsers(usersRes, statsRes.monthly_limit);\n    renderTransactions(txRes);\n  } catch (err) {\n    console.error(\'Error fetching dashboard telemetry:\', err);\n  }\n}\n\nfunction renderStats(stats) {\n  if (!stats) return;\n\n  document.getElementById(\'stat-total-dispensed\').textContent = stats.total_dispensed || 0;\n  document.getElementById(\'stat-today-tx\').textContent = stats.today_transactions || 0;\n  document.getElementById(\'stat-active-users\').textContent = stats.registered_users || 0;\n  document.getElementById(\'stat-monthly-limit\').textContent = stats.monthly_limit || 5;\n\n  // Render Database & Device connection\n  const conn = stats.connection || {};\n  const dbBadge = document.getElementById(\'db-badge\');\n  const dbTitle = document.getElementById(\'db-title\');\n  const dbDesc = document.getElementById(\'db-desc\');\n\n  if (conn.connected) {\n    dbBadge.textContent = "MongoDB Atlas Live";\n    dbBadge.className = "banner-badge";\n    dbTitle.textContent = "MongoDB Atlas Cluster Synchronized";\n    dbDesc.textContent = "All transactions, users, and device telemetry are persistently synced with your MongoDB Atlas cloud database.";\n  } else {\n    dbBadge.textContent = "Local Fallback Cache";\n    dbBadge.className = "banner-badge badge-warn";\n    dbTitle.textContent = "Operating in Resilient Mode";\n    dbDesc.textContent = conn.error ? `Atlas Notice: ${conn.error}. System is running smoothly in local storage mode.` : "Connecting to database...";\n  }\n\n  // Device status\n  const devStatusText = document.getElementById(\'device-status-text\');\n  const devices = stats.devices || [];\n  const activeDevice = devices.find(d => d.is_active);\n  if (activeDevice) {\n    devStatusText.textContent = `${activeDevice.device_id}: Online`;\n  } else {\n    devStatusText.textContent = "UNO R4 WiFi: Ready";\n  }\n}\n\nfunction renderUsers(users, defaultLimit = 5) {\n  const tbody = document.getElementById(\'users-tbody\');\n  if (!users || users.length === 0) {\n    tbody.innerHTML = \'<tr><td colspan="6" class="text-center text-muted py-4">No beneficiaries registered yet. Click "Add User" above.</td></tr>\';\n    return;\n  }\n\n  tbody.innerHTML = users.map(u => {\n    const limit = u.monthly_limit || defaultLimit;\n    const used = u.used_pads || 0;\n    const remaining = Math.max(0, limit - used);\n    const pct = Math.min(Math.round((used / limit) * 100), 100);\n    const isExhausted = remaining === 0;\n\n    const statusBadge = isExhausted\n      ? \'<span class="badge badge-warn">Limit Reached</span>\'\n      : \'<span class="badge badge-emerald">Active</span>\';\n\n    return `\n      <tr>\n        <td><strong>${escapeHtml(u.name)}</strong></td>\n        <td><code class="font-mono">${escapeHtml(u.rfid_uid)}</code></td>\n        <td>\n          <div style="font-size:12px; font-weight:600">${used} / ${limit} pads</div>\n          <div class="progress-wrap">\n            <div class="progress-bar ${isExhausted ? \'limit-reached\' : \'\'}" style="width: ${pct}%"></div>\n          </div>\n        </td>\n        <td><strong style="color:${isExhausted ? \'#f59e0b\' : \'#34d399\'}">${remaining}</strong> pads</td>\n        <td>${statusBadge}</td>\n        <td>\n          <button class="btn btn-secondary btn-sm" onclick="resetSingleUser(\'${escapeHtml(u.rfid_uid)}\')">Reset</button>\n        </td>\n      </tr>\n    `;\n  }).join(\'\');\n}\n\nfunction renderTransactions(txs) {\n  const tbody = document.getElementById(\'tx-tbody\');\n  if (!txs || txs.length === 0) {\n    tbody.innerHTML = \'<tr><td colspan="5" class="text-center text-muted py-4">No dispense activity yet. Tap a card in the simulator to test!</td></tr>\';\n    return;\n  }\n\n  tbody.innerHTML = txs.map(t => {\n    let badgeClass = \'badge-emerald\';\n    let statusLabel = \'Dispensed\';\n\n    if (t.status === \'DENIED_LIMIT_REACHED\') {\n      badgeClass = \'badge-warn\';\n      statusLabel = \'Quota Exceeded\';\n    } else if (t.status === \'INVALID_CARD\') {\n      badgeClass = \'badge-err\';\n      statusLabel = \'Invalid Card\';\n    }\n\n    return `\n      <tr>\n        <td>${escapeHtml(t.user_name || \'Unknown\')}</td>\n        <td><code class="font-mono">${escapeHtml(t.rfid_uid)}</code></td>\n        <td><strong>${t.quantity > 0 ? t.quantity : \'—\'}</strong></td>\n        <td><span class="badge ${badgeClass}">${statusLabel}</span></td>\n        <td style="color:var(--text-dim); font-size:12px;">${escapeHtml(t.timestamp || \'\')}</td>\n      </tr>\n    `;\n  }).join(\'\');\n}\n\n// ------------------------------------------------------------\n//  INTERACTIVE HARDWARE & DISPENSER SIMULATOR\n// ------------------------------------------------------------\n\nfunction toggleSimulator() {\n  const container = document.getElementById(\'simulator-container\');\n  container.classList.toggle(\'hidden\');\n  if (!container.classList.contains(\'hidden\')) {\n    container.scrollIntoView({ behavior: \'smooth\', block: \'center\' });\n  }\n}\n\nasync function simTapCard(uid) {\n  if (currentSimState.isBusy) return;\n\n  setOledText("AUTHENTICATING...", "CONNECTING HTTPS", "CHECKING VERCEL");\n\n  try {\n    const res = await fetch(\'/api/card/verify\', {\n      method: \'POST\',\n      headers: {\n        \'Content-Type\': \'application/json\',\n        \'X-Client\': \'WebSimulator\'\n      },\n      body: JSON.stringify({ uid: uid, device_id: \'SIMULATOR-01\' })\n    });\n\n    const data = await res.json();\n\n    if (data.authorized) {\n      currentSimState.activeUid = uid;\n      currentSimState.activeName = data.name;\n      currentSimState.remaining = data.remaining;\n      currentSimState.maxSelectable = data.max_selectable;\n      currentSimState.selectedQty = 1;\n\n      setOledText(\n        data.name.toUpperCase(),\n        `REMAINING: ${data.remaining}`,\n        `SELECT: [ 1 ] PAD`\n      );\n      showToast(`Card Verified: ${data.name} (${data.remaining} pads available)`, \'success\');\n    } else {\n      currentSimState.activeUid = null;\n      if (data.reason === \'LIMIT_REACHED\') {\n        setOledText(data.name.toUpperCase(), "LIMIT REACHED", "0 PADS REMAINING");\n        showToast(`Limit Reached: ${data.name} has exhausted monthly quota.`, \'error\');\n      } else {\n        setOledText("INVALID CARD", "NOT REGISTERED", "TAP VALID CARD");\n        showToast("Card not registered in database.", \'error\');\n      }\n\n      setTimeout(resetOledIdle, 3500);\n    }\n  } catch (err) {\n    setOledText("SERVER ERROR", "CHECK CONNECTION", "TRY AGAIN");\n    setTimeout(resetOledIdle, 3000);\n  }\n}\n\nfunction simTapCustomCard() {\n  const input = document.getElementById(\'sim-custom-uid\');\n  const uid = input.value.trim().toUpperCase();\n  if (!uid) {\n    showToast("Please enter a card UID", \'error\');\n    return;\n  }\n  simTapCard(uid);\n}\n\nfunction simAdjustQty(delta) {\n  if (!currentSimState.activeUid || currentSimState.isBusy) return;\n\n  const newQty = currentSimState.selectedQty + delta;\n  if (newQty >= 1 && newQty <= currentSimState.maxSelectable) {\n    currentSimState.selectedQty = newQty;\n    setOledText(\n      currentSimState.activeName.toUpperCase(),\n      `REMAINING: ${currentSimState.remaining}`,\n      `SELECT: [ ${newQty} ] PADS`\n    );\n  }\n}\n\nasync function simConfirmDispense() {\n  if (!currentSimState.activeUid || currentSimState.isBusy) return;\n\n  currentSimState.isBusy = true;\n  const qty = currentSimState.selectedQty;\n  const uid = currentSimState.activeUid;\n\n  setOledText("COMMITTING...", `REQUESTING ${qty} PADS`, "CONTACTING CLOUD");\n\n  try {\n    const res = await fetch(\'/api/dispense/complete\', {\n      method: \'POST\',\n      headers: {\n        \'Content-Type\': \'application/json\',\n        \'X-Client\': \'WebSimulator\'\n      },\n      body: JSON.stringify({\n        uid: uid,\n        device_id: \'SIMULATOR-01\',\n        quantity: qty\n      })\n    });\n\n    const data = await res.json();\n\n    if (data.success) {\n      showToast(`Dispensing ${qty} pads for ${data.user_name}...`, \'success\');\n\n      // Animate Servos\n      for (let i = 1; i <= qty; i++) {\n        setOledText("DISPENSING...", `PAD ${i} OF ${qty}`, "PLEASE WAIT");\n        await runServoCycle();\n      }\n\n      setOledText("THANK YOU!", "COLLECT PADS", `REMAINING: ${data.remaining}`);\n      showToast("Dispense cycle complete!", \'success\');\n      fetchDashboardData();\n    } else {\n      setOledText("TRANSACTION FAILED", data.reason || "ERROR", "TRY AGAIN");\n      showToast(data.message || "Dispense denied", \'error\');\n    }\n  } catch (err) {\n    setOledText("DISPENSE ERROR", "SERVER TIMEOUT", "PLEASE RETRY");\n  } finally {\n    currentSimState.isBusy = false;\n    currentSimState.activeUid = null;\n    setTimeout(resetOledIdle, 4000);\n  }\n}\n\nasync function runServoCycle() {\n  const arm = document.getElementById(\'sim-servo-arm\');\n  const gate = document.getElementById(\'sim-servo-gate\');\n\n  // Step 1: Arm actuates (moves pad forward)\n  arm.classList.add(\'actuated\');\n  await sleep(700);\n\n  // Step 2: Gate opens (drops pad)\n  gate.classList.add(\'actuated\');\n  await sleep(700);\n\n  // Step 3: Arm returns to home\n  arm.classList.remove(\'actuated\');\n  await sleep(600);\n\n  // Step 4: Gate returns to home\n  gate.classList.remove(\'actuated\');\n  await sleep(600);\n}\n\nfunction setOledText(line1, line2, line3) {\n  document.getElementById(\'sim-oled-line1\').textContent = line1;\n  document.getElementById(\'sim-oled-line2\').textContent = line2;\n  document.getElementById(\'sim-oled-line3\').textContent = line3;\n}\n\nfunction resetOledIdle() {\n  setOledText("HYGIENET R4", "READY TO SCAN", "TAP RFID CARD");\n}\n\n// ------------------------------------------------------------\n//  BENEFICIARY MANAGEMENT MODAL & RESET\n// ------------------------------------------------------------\n\nfunction openAddUserModal() {\n  document.getElementById(\'user-form\').reset();\n  document.getElementById(\'user-modal\').classList.remove(\'hidden\');\n}\n\nfunction closeUserModal() {\n  document.getElementById(\'user-modal\').classList.add(\'hidden\');\n}\n\nasync function handleUserSubmit(e) {\n  e.preventDefault();\n  const name = document.getElementById(\'form-name\').value.trim();\n  const uid = document.getElementById(\'form-uid\').value.trim().toUpperCase();\n  const limit = parseInt(document.getElementById(\'form-limit\').value, 10);\n\n  try {\n    const res = await fetch(\'/api/users\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({ rfid_uid: uid, name: name, monthly_limit: limit })\n    });\n    const data = await res.json();\n    if (data.success) {\n      showToast(data.message, \'success\');\n      closeUserModal();\n      fetchDashboardData();\n    } else {\n      showToast(data.message || \'Failed to save beneficiary\', \'error\');\n    }\n  } catch (err) {\n    showToast(\'Network error saving user\', \'error\');\n  }\n}\n\nasync function resetSingleUser(uid) {\n  if (!confirm(`Reset monthly pad usage to 0 for card ${uid}?`)) return;\n\n  try {\n    const res = await fetch(\'/api/users/reset\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({ rfid_uid: uid })\n    });\n    const data = await res.json();\n    showToast(data.message, \'success\');\n    fetchDashboardData();\n  } catch (err) {\n    showToast(\'Failed to reset quota\', \'error\');\n  }\n}\n\nasync function confirmResetAll() {\n  if (!confirm("Are you sure you want to reset the monthly pad usage to 0 for ALL registered beneficiaries?")) return;\n\n  try {\n    const res = await fetch(\'/api/users/reset\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({})\n    });\n    const data = await res.json();\n    showToast(data.message, \'success\');\n    fetchDashboardData();\n  } catch (err) {\n    showToast(\'Failed to reset quotas\', \'error\');\n  }\n}\n\n// ------------------------------------------------------------\n//  TOAST UTILITY & HELPERS\n// ------------------------------------------------------------\n\nfunction showToast(message, type = \'info\') {\n  const container = document.getElementById(\'toast-container\');\n  const toast = document.createElement(\'div\');\n  toast.className = `toast toast-${type}`;\n  toast.textContent = message;\n  container.appendChild(toast);\n\n  setTimeout(() => {\n    toast.style.opacity = \'0\';\n    toast.style.transform = \'translateY(10px)\';\n    setTimeout(() => toast.remove(), 300);\n  }, 4000);\n}\n\nfunction sleep(ms) {\n  return new Promise(resolve => setTimeout(resolve, ms));\n}\n\nfunction escapeHtml(str) {\n  if (!str) return \'\';\n  return String(str)\n    .replace(/&/g, \'&amp;\')\n    .replace(/</g, \'&lt;\')\n    .replace(/>/g, \'&gt;\')\n    .replace(/"/g, \'&quot;\')\n    .replace(/\'/g, \'&#039;\');\n}\n'
